const terreno = await cargarModelo('00_mapa/terreno_mapa');
colocar(terreno, { x: 0, y: 0, z: 0 });

const lago = await cargarModelo('09_camino_agua/lago_v1');
colocar(lago, { x: 34, z: -44, rot: 0.3, escala: 1.9 });

for (const casa of ['polimotor', 'expresion_artistica',
  'multisaberes', 'multisensorial', 'tecnologia']) {
  const m = await cargarModelo(`07_casas_tematicas/casa_${casa}`);
  colocar(m, { x, z, rot: mirarAlCamino(x, z) });
}

const marcador = await cargarModelo('10_props/marcador_nivel');
casas.forEach((casa, i) =>
  colocar(marcador, { x: casa.mx, z: casa.mz, escala: 1.9 }));

const valla = await cargarModelo('10_props/valla_3m');
// 9 tramos en arco alrededor del lago pequeño

const pinos = ['pino_v1', 'pino_v2', 'pino_v3', 'pino_alto_v1', …];
while (colocados < 320) {
  const { x, z } = puntoAleatorio();
  if (!libre(x, z)) continue;       // camino, casas, lagos
  colocar(await cargarModelo(azar(pinos)), { x, z, rot: azar(0, 6.28), escala: azar(0.85, 1.6) });
}

const flores = ['margarita', 'tulipan_v1', 'girasol', 'campanula', 'flor_silvestre_v2', …];
for (const grupo of grupos) {
  for (let i = 0; i < azar(1, 3); i++)
    colocar(await cargarModelo(`03_flores_suelo/${azar(flores)}`), cerca(grupo, 0.8));
}

for (let i = 0; i < 34; i++) {
  const angulo = i / 34 * 2 * Math.PI, radio = azar(175, 230);
  colocar(await cargarModelo(`01_relieve/montana_nevada_v${azar(1, 3)}`),
    { x: Math.cos(angulo) * radio, z: Math.sin(angulo) * radio, escala: azar(1.4, 3) });
}

// los animales no se instancian: cada uno es una copia con comportamiento
const conejo = await cargarModelo('04_animales/conejo_v1');
fauna.agregar(conejo, { p: [x, y, z], r, s: 1.3 });

// cada frame: caminar, pastar, nadar, volar o revolotear
fauna.update(dt, tiempo);
